package com.kmarket.ordersservice.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.Generated;
import org.hibernate.generator.EventType;

import java.time.OffsetDateTime;

/**
 * A customer from {@code orders.customers}.
 *
 * <p>Identity model: {@code orders.customers.id == auth.users.id == JWT sub}. The id is
 * <b>owned and generated by Auth Service</b> and assigned explicitly here — it is NOT a
 * database-generated sequence (no {@code @GeneratedValue}). There is deliberately no
 * cross-service foreign key to {@code auth.users}; the equality is a logical contract.</p>
 */
@Entity
@Table(name = "customers", schema = "orders")
@Getter
@Setter
@NoArgsConstructor
public class Customer {

    /** The Auth user id (JWT {@code sub}); assigned by the caller, never DB-generated. */
    @Id
    private Integer id;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false, unique = true)
    private String email;

    @Generated(event = EventType.INSERT)
    @Column(name = "created_at", nullable = false, insertable = false, updatable = false)
    private OffsetDateTime createdAt;
}
